const items = $input.all();
const members = (items[0].json.members || []).filter(m => !m.is_bot && !m.deleted && m.id !== 'USLACKBOT');

// We'll simulate presence check — in production, use users.getPresence for each
const results = members.map(m => ({
  userId: m.id,
  name: m.real_name || m.name || 'Unknown',
  statusText: (m.profile || {}).status_text || '',
  statusEmoji: (m.profile || {}).status_emoji || '',
  title: (m.profile || {}).title || '',
  tz: m.tz || 'UTC'
}));

return results.map(r => ({json: r}));

const items = $input.all();

const matrix = {
  active: [],
  away: [],
  dnd: [],
  offline: []
};

for (const item of items) {
  const data = item.json;
  const presence = data.presence || 'away';
  const name = data.name || 'Unknown';
  const status = data.statusText ? ` (${data.statusEmoji} ${data.statusText})` : '';

  if (presence === 'active') {
    matrix.active.push(`<@${data.userId}>${status}`);
  } else {
    matrix.away.push(`<@${data.userId}>${status}`);
  }
}

let reply = `:busts_in_silhouette: *Team Availability*\n\n`;
reply += `:green_circle: *Available (${matrix.active.length}):*\n`;
reply += matrix.active.length > 0 ? matrix.active.join('\n') : '_No one currently active_';
reply += `\n\n:red_circle: *Away (${matrix.away.length}):*\n`;
reply += matrix.away.length > 0 ? matrix.away.join('\n') : '_Everyone is available!_';
reply += `\n\n_Checked at ${new Date().toLocaleTimeString()}_`;

return [{json: {reply, activeCount: matrix.active.length, awayCount: matrix.away.length}}];
